<?php
namespace App\Application\Security;use App\Application\Audit\AuditWriter;use App\Models\{PrivilegedAccessGrant,User};use Illuminate\Support\{Facades\DB,Str};use Illuminate\Validation\ValidationException;
final class PrivilegedAccessService{public function __construct(private AuditWriter$a){}public function request(string$tenant,User$target,array$d,User$requester):PrivilegedAccessGrant{if($d['expires_at']<=now()||$d['starts_at']>=$d['expires_at'])throw ValidationException::withMessages(['expires_at'=>__('wave9.access_window_invalid')]);$scope=$d['scope'];sort($scope);return PrivilegedAccessGrant::create([...$d,'tenant_id'=>$tenant,'user_id'=>$target->id,'requested_by'=>$requester->id,'approved_by'=>$requester->id,'status'=>'REQUESTED','scope'=>$scope,'scope_hash'=>hash('sha256',json_encode($scope))]);}/** REQ-DUP-009: single-step grant (legacy compliance/privileged-access contract): the caller is the approver and may not be the grantee. */public function grant(string$tenant,User$target,array$d,User$approver):PrivilegedAccessGrant{if($target->id===$approver->id)abort(403,'Users cannot approve their own privileged access.');if($d['starts_at']>=$d['expires_at'])throw ValidationException::withMessages(['expires_at'=>__('wave9.access_window_invalid')]);$scope=$d['scope']??[];sort($scope);$g=PrivilegedAccessGrant::create(['purpose'=>$d['purpose'],'justification'=>$d['justification'],'starts_at'=>$d['starts_at'],'expires_at'=>$d['expires_at'],'tenant_id'=>$tenant,'user_id'=>$target->id,'requested_by'=>$approver->id,'approved_by'=>$approver->id,'status'=>'APPROVED','scope'=>$scope,'scope_hash'=>hash('sha256',json_encode($scope))]);$this->event($g,'APPROVED',$approver,$g->purpose);$this->a->record('privileged_access.granted','privileged_access_grant',$g->id,['user_id'=>$target->id,'tenant_id'=>$tenant]);return$g;}public function approve(PrivilegedAccessGrant$g,User$u):PrivilegedAccessGrant{if($g->status!=='REQUESTED'||$g->requested_by===$u->id||$g->user_id===$u->id)throw ValidationException::withMessages(['status'=>__('wave9.maker_checker')]);$g->update(['status'=>'APPROVED','approved_by'=>$u->id]);$this->event($g,'APPROVED',$u,$g->purpose);return$g->refresh();}public function use(PrivilegedAccessGrant$g,string$type,string$id,string$purpose,User$u):void{if($g->user_id!==$u->id||$g->status!=='APPROVED'||!now()->between($g->starts_at,$g->expires_at)||$g->revoked_at)throw ValidationException::withMessages(['access'=>__('wave9.access_denied')]);$this->event($g,'USED',$u,$purpose,$type,$id);$this->a->record('privileged_access.used',$type,$id,['grant_id'=>$g->id,'purpose'=>$purpose]);}public function revoke(PrivilegedAccessGrant$g,string$reason,User$u):PrivilegedAccessGrant{$g->update(['status'=>'REVOKED','revoked_at'=>now(),'revoked_by'=>$u->id,'revocation_reason'=>$reason]);$this->event($g,'REVOKED',$u,$reason);return$g->refresh();}private function event(PrivilegedAccessGrant$g,string$e,User$u,string$p,?string$t=null,?string$i=null):void{DB::table('privileged_access_events')->insert(['id'=>(string)Str::uuid(),'privileged_access_grant_id'=>$g->id,'event_type'=>$e,'actor_id'=>$u->id,'purpose'=>$p,'resource_type'=>$t,'resource_id'=>$i,'metadata'=>'{}','occurred_at'=>now()]);}}
